window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-66ac57c593e09a10"]={"versions": [{"id": "FIG-66ac57c593e09a10", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Architektur- und Notationsdiagramm zur standardisierten grafischen Notation von Software-Komponenten (<code>AUTOSAR-SW-Component</code>), deren Port-Prototypen (<code>PortPrototype</code>) und Verbindungsleitungen (<code>ConnectorPrototype</code>) gemäß AUTOSAR Software Component Template.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist eine Software-Komponente (<code>AUTOSAR-SW-Component</code>), dargestellt als grauer Rechteckblock. An ihrer Schnittstellengrenze befinden sich sechs beispielhafte Port-Prototypen (<code>PortPrototype</code>), typisiert durch ein jeweiliges <code>PortInterface</code>:</p>\n<ul class=\"fig-list\"><li>Oberster Port: Bereitgestellter Client-Server-Port (<code>provided PortPrototype, ClientServerInterface.</code>), symbolisiert durch ein Quadrat mit vollständigem Kreis.\n</li><li>Zweiter Port: Anfordernder Client-Server-Port (<code>required PortPrototype, ClientServerInterface.</code>), symbolisiert durch ein Quadrat mit nach innen gewölbtem Halbkreisbecher; daran angebunden eine Verbindungslinie (<code>ConnectorPrototype</code>) zu einer Gegenstelle mit Vollkreis.\n</li><li>Dritter Port: Bereitgestellter Sender-Receiver-Port (<code>provided PortPrototype, SenderReceiverInterface</code>), symbolisiert durch ein Quadrat mit nach außen gerichtetem schwarzen Dreieck.\n</li><li>Vierter Port: Anfordernder Sender-Receiver-Port (<code>required PortPrototype, SenderReceiverInterface</code>), symbolisiert durch ein Quadrat mit nach innen gerichtetem schwarzen Dreieck; daran angebunden ein <code>ConnectorPrototype</code> zu einer Gegenstelle mit nach innen gerichtetem Dreieck.\n</li><li>Fünfter Port: Anfordernder Service-Port (<code>required service PortPrototype, SenderReceiverInterface</code>), symbolisiert durch ein geteiltes Quadrat (linke Hälfte schwarz, rechte Hälfte mit nach innen gerichtetem Dreieck) sowie einen angeschlossenen massiven schwarzen Kasten.\n</li><li>Sechster Port: Bereitgestellter Sender-Receiver-Port (<code>provided PortPrototype, SenderReceiverInterface</code>) mit einem Notiz-Kästchen <code>attributes</code>.\n</li></ul>\n<p class=\"fig-p\">Die Beschriftung <code>PortPrototype characterised by PortInterface</code> verweist per Pfeil auf das Quadrat-Symbol.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Notationsschema ohne dynamische Ablauf- oder Sequenzpfade. Dargestellt ist das Kopplungsprinzip für Client-Server- und Sender-Receiver-Kommunikation über ConnectorPrototypes zwischen korrespondierenden Ports.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert die verbindliche grafische Syntax für Tooling und Spezifikationsdokumente: Bereitstellung (Provided) versus Anforderung (Required), Trennung der Kommunikationsmuster (Client-Server als Lollipop/Cup, Sender-Receiver als gerichtete Dreiecke), Kennzeichnung von Service-Ports sowie die Anbringung von Port-Attributen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-846d2014d3a3e244", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Architektur- und Notationsdiagramm zur standardisierten grafischen Notation von Software-Komponenten (<code>AUTOSAR-SW-Component</code>), deren Port-Prototypen (<code>PortPrototype</code>) und Verbindungsleitungen (<code>ConnectorPrototype</code>) gemäß AUTOSAR Software Component Template.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist eine Software-Komponente (<code>AUTOSAR-SW-Component</code>), dargestellt als grauer Rechteckblock. An ihrer Schnittstellengrenze befinden sich sechs beispielhafte Port-Prototypen (<code>PortPrototype</code>), typisiert durch ein jeweiliges <code>PortInterface</code>:</p>\n<ul class=\"fig-list\"><li>Oberster Port: Bereitgestellter Client-Server-Port (<code>provided PortPrototype, ClientServerInterface.</code>), symbolisiert durch ein Quadrat mit vollständigem Kreis.\n</li><li>Zweiter Port: Anfordernder Client-Server-Port (<code>required PortPrototype, ClientServerInterface.</code>), symbolisiert durch ein Quadrat mit nach innen gewölbtem Halbkreisbecher; daran angebunden eine Verbindungslinie (<code>ConnectorPrototype</code>) zu einer Gegenstelle mit Vollkreis.\n</li><li>Dritter Port: Bereitgestellter Sender-Receiver-Port (<code>provided PortPrototype, SenderReceiverInterface</code>), symbolisiert durch ein Quadrat mit nach außen gerichtetem schwarzen Dreieck.\n</li><li>Vierter Port: Anfordernder Sender-Receiver-Port (<code>required PortPrototype, SenderReceiverInterface</code>), symbolisiert durch ein Quadrat mit nach innen gerichtetem schwarzen Dreieck; daran angebunden ein <code>ConnectorPrototype</code> zu einer Gegenstelle mit nach innen gerichtetem Dreieck.\n</li><li>Fünfter Port: Anfordernder Service-Port (<code>required service PortPrototype, SenderReceiverInterface</code>), symbolisiert durch ein geteiltes Quadrat (linke Hälfte schwarz, rechte Hälfte mit nach innen gerichtetem Dreieck) sowie einen angeschlossenen massiven schwarzen Kasten.\n</li><li>Sechster Port: Bereitgestellter Sender-Receiver-Port (<code>provided PortPrototype, SenderReceiverInterface</code>) mit einem Notiz-Kästchen <code>attributes</code>.\n</li></ul>\n<p class=\"fig-p\">Die Beschriftung <code>PortPrototype characterised by PortInterface</code> verweist per Pfeil auf das Quadrat-Symbol.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Notationsschema ohne dynamische Ablauf- oder Sequenzpfade. Dargestellt ist das Kopplungsprinzip für Client-Server- und Sender-Receiver-Kommunikation über ConnectorPrototypes zwischen korrespondierenden Ports.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert die verbindliche grafische Syntax für Tooling und Spezifikationsdokumente: Bereitstellung (Provided) versus Anforderung (Required), Trennung der Kommunikationsmuster (Client-Server als Lollipop/Cup, Sender-Receiver als gerichtete Dreiecke), Kennzeichnung von Service-Ports sowie die Anbringung von Port-Attributen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-1a30d45a66d49758", "releases": ["R4.0.3", "R4.1.3", "R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Architektur- und Notationsdiagramm zur standardisierten grafischen Notation von Software-Komponenten (<code>AUTOSAR-SW-Component</code>), deren Port-Prototypen (<code>PortPrototype</code>) und Verbindungsleitungen (<code>ConnectorPrototype</code>) gemäß AUTOSAR Software Component Template.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist eine Software-Komponente (<code>AUTOSAR-SW-Component</code>), dargestellt als grauer Rechteckblock. An ihrer Schnittstellengrenze befinden sich sechs beispielhafte Port-Prototypen (<code>PortPrototype</code>), typisiert durch ein jeweiliges <code>PortInterface</code>:</p>\n<ul class=\"fig-list\"><li>Oberster Port: Bereitgestellter Client-Server-Port (<code>provided PortPrototype, ClientServerInterface.</code>), symbolisiert durch ein Quadrat mit vollständigem Kreis.\n</li><li>Zweiter Port: Anfordernder Client-Server-Port (<code>required PortPrototype, ClientServerInterface.</code>), symbolisiert durch ein Quadrat mit nach innen gewölbtem Halbkreisbecher; daran angebunden eine Verbindungslinie (<code>ConnectorPrototype</code>) zu einer Gegenstelle mit Vollkreis.\n</li><li>Dritter Port: Bereitgestellter Sender-Receiver-Port (<code>provided PortPrototype, SenderReceiverInterface</code>), symbolisiert durch ein Quadrat mit nach außen gerichtetem schwarzen Dreieck.\n</li><li>Vierter Port: Anfordernder Sender-Receiver-Port (<code>required PortPrototype, SenderReceiverInterface</code>), symbolisiert durch ein Quadrat mit nach innen gerichtetem schwarzen Dreieck; daran angebunden ein <code>ConnectorPrototype</code> zu einer Gegenstelle mit nach innen gerichtetem Dreieck.\n</li><li>Fünfter Port: Anfordernder Service-Port (<code>required service PortPrototype, SenderReceiverInterface</code>), symbolisiert durch ein geteiltes Quadrat (linke Hälfte schwarz, rechte Hälfte mit nach innen gerichtetem Dreieck) sowie einen angeschlossenen massiven schwarzen Kasten.\n</li><li>Sechster Port: Bereitgestellter Sender-Receiver-Port (<code>provided PortPrototype, SenderReceiverInterface</code>) mit einem Notiz-Kästchen <code>attributes</code>.\n</li></ul>\n<p class=\"fig-p\">Die Beschriftung <code>PortPrototype characterised by PortInterface</code> verweist per Pfeil auf das Quadrat-Symbol.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Notationsschema ohne dynamische Ablauf- oder Sequenzpfade. Dargestellt ist das Kopplungsprinzip für Client-Server- und Sender-Receiver-Kommunikation über ConnectorPrototypes zwischen korrespondierenden Ports.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert die verbindliche grafische Syntax für Tooling und Spezifikationsdokumente: Bereitstellung (Provided) versus Anforderung (Required), Trennung der Kommunikationsmuster (Client-Server als Lollipop/Cup, Sender-Receiver als gerichtete Dreiecke), Kennzeichnung von Service-Ports sowie die Anbringung von Port-Attributen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-b489fff0ef1f19c9", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Architektur- und Notationsdiagramm zur standardisierten grafischen Notation von Software-Komponenten (<code>AUTOSAR-SW-Component</code>), deren Port-Prototypen (<code>PortPrototype</code>) und Verbindungsleitungen (<code>ConnectorPrototype</code>) gemäß AUTOSAR Software Component Template.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist eine Software-Komponente (<code>AUTOSAR-SW-Component</code>), dargestellt als grauer Rechteckblock. An ihrer Schnittstellengrenze befinden sich sechs beispielhafte Port-Prototypen (<code>PortPrototype</code>), typisiert durch ein jeweiliges <code>PortInterface</code>:</p>\n<ul class=\"fig-list\"><li>Oberster Port: Bereitgestellter Client-Server-Port (<code>provided PortPrototype, ClientServerInterface.</code>), symbolisiert durch ein Quadrat mit vollständigem Kreis.\n</li><li>Zweiter Port: Anfordernder Client-Server-Port (<code>required PortPrototype, ClientServerInterface.</code>), symbolisiert durch ein Quadrat mit nach innen gewölbtem Halbkreisbecher; daran angebunden eine Verbindungslinie (<code>ConnectorPrototype</code>) zu einer Gegenstelle mit Vollkreis.\n</li><li>Dritter Port: Bereitgestellter Sender-Receiver-Port (<code>provided PortPrototype, SenderReceiverInterface</code>), symbolisiert durch ein Quadrat mit nach außen gerichtetem schwarzen Dreieck.\n</li><li>Vierter Port: Anfordernder Sender-Receiver-Port (<code>required PortPrototype, SenderReceiverInterface</code>), symbolisiert durch ein Quadrat mit nach innen gerichtetem schwarzen Dreieck; daran angebunden ein <code>ConnectorPrototype</code> zu einer Gegenstelle mit nach innen gerichtetem Dreieck.\n</li><li>Fünfter Port: Anfordernder Service-Port (<code>required service PortPrototype, SenderReceiverInterface</code>), symbolisiert durch ein geteiltes Quadrat (linke Hälfte schwarz, rechte Hälfte mit nach innen gerichtetem Dreieck) sowie einen angeschlossenen massiven schwarzen Kasten.\n</li><li>Sechster Port: Bereitgestellter Sender-Receiver-Port (<code>provided PortPrototype, SenderReceiverInterface</code>) mit einem Notiz-Kästchen <code>attributes</code>.\n</li></ul>\n<p class=\"fig-p\">Die Beschriftung <code>PortPrototype characterised by PortInterface</code> verweist per Pfeil auf das Quadrat-Symbol.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Notationsschema ohne dynamische Ablauf- oder Sequenzpfade. Dargestellt ist das Kopplungsprinzip für Client-Server- und Sender-Receiver-Kommunikation über ConnectorPrototypes zwischen korrespondierenden Ports.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert die verbindliche grafische Syntax für Tooling und Spezifikationsdokumente: Bereitstellung (Provided) versus Anforderung (Required), Trennung der Kommunikationsmuster (Client-Server als Lollipop/Cup, Sender-Receiver als gerichtete Dreiecke), Kennzeichnung von Service-Ports sowie die Anbringung von Port-Attributen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-cee87488e807a4d5", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Architektur- und Notationsdiagramm zur standardisierten grafischen Notation von Software-Komponenten (<code>AUTOSAR Software-Component</code>), deren Port-Prototypen (<code>PortPrototype</code>) und Verbindungsleitungen (<code>SwConnector</code>) gemäß AUTOSAR Software Component Template.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist eine Software-Komponente (<code>AUTOSAR Software-Component</code>), dargestellt als grauer Rechteckblock. An ihrer Schnittstellengrenze befinden sich sechs beispielhafte Port-Prototypen (<code>PortPrototype</code>), charakterisiert durch ein <code>PortInterface</code>:</p>\n<ul class=\"fig-list\"><li>Oberster Port: Bereitgestellter Client-Server-Port (<code>provided PortPrototype, ClientServerInterface</code>), symbolisiert durch ein Quadrat mit vollständigem Kreis.\n</li><li>Zweiter Port: Anfordernder Client-Server-Port (<code>required PortPrototype, ClientServerInterface</code>), symbolisiert durch ein Quadrat mit nach innen gewölbtem Halbkreisbecher; daran angebunden eine Verbindungslinie (<code>SwConnector</code>) zu einer Gegenstelle mit Vollkreis.\n</li><li>Dritter Port: Bereitgestellter Sender-Receiver-Port (<code>provided PortPrototype, SenderReceiverInterface</code>), symbolisiert durch ein Quadrat mit nach außen gerichtetem schwarzen Dreieck.\n</li><li>Vierter Port: Anfordernder Sender-Receiver-Port (<code>required PortPrototype, SenderReceiverInterface</code>), symbolisiert durch ein Quadrat mit nach innen gerichtetem schwarzen Dreieck; daran angebunden ein <code>SwConnector</code> zu einer Gegenstelle mit nach innen gerichtetem Dreieck.\n</li><li>Fünfter Port: Anfordernder Service-Port mit Verbindung zu einem massiven schwarzen Block (<code>required service PortPrototype, SenderReceiverInterface</code>).\n</li><li>Sechster Port: Bereitgestellter Sender-Receiver-Port (<code>provided PortPrototype, SenderReceiverInterface</code>) mit angehängtem Notiz-Symbol <code>attributes</code>.\n</li></ul>\n<p class=\"fig-p\">Ein Pfeil mit der Beschriftung <code>PortPrototype characterised by PortInterface</code> weist auf das Port-Symbol hin.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Notationsschema ohne dynamische Ablauf- oder Sequenzpfade. Dargestellt ist das Kopplungsprinzip für Client-Server- und Sender-Receiver-Kommunikation über <code>SwConnector</code> zwischen korrespondierenden Ports.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert die verbindliche grafische Syntax für Tooling und Spezifikationsdokumente: Bereitstellung (Provided) versus Anforderung (Required), Trennung der Kommunikationsmuster (Client-Server als Lollipop/Cup, Sender-Receiver als gerichtete Dreiecke), Kennzeichnung von Service-Ports sowie die Anbringung von Port-Attributen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-1eea46e01abb7ab7", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Architektur- und Notationsdiagramm zur standardisierten grafischen Notation von Software-Komponenten (<code>AUTOSAR Software-Component</code>), deren Port-Prototypen (<code>PortPrototype</code>) und Verbindungsleitungen (<code>SwConnector</code>) gemäß AUTOSAR Software Component Template.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist eine Software-Komponente (<code>AUTOSAR Software-Component</code>), dargestellt als grauer Rechteckblock. An ihrer Schnittstellengrenze befinden sich sechs beispielhafte Port-Prototypen (<code>PortPrototype</code>), charakterisiert durch ein <code>PortInterface</code>:</p>\n<ul class=\"fig-list\"><li>Oberster Port: Bereitgestellter Client-Server-Port (<code>provided PortPrototype, ClientServerInterface</code>), symbolisiert durch ein Quadrat mit vollständigem Kreis.\n</li><li>Zweiter Port: Anfordernder Client-Server-Port (<code>required PortPrototype, ClientServerInterface</code>), symbolisiert durch ein Quadrat mit nach innen gewölbtem Halbkreisbecher; daran angebunden eine Verbindungslinie (<code>SwConnector</code>) zu einer Gegenstelle mit Vollkreis.\n</li><li>Dritter Port: Bereitgestellter Sender-Receiver-Port (<code>provided PortPrototype, SenderReceiverInterface</code>), symbolisiert durch ein Quadrat mit nach außen gerichtetem schwarzen Dreieck.\n</li><li>Vierter Port: Anfordernder Sender-Receiver-Port (<code>required PortPrototype, SenderReceiverInterface</code>), symbolisiert durch ein Quadrat mit nach innen gerichtetem schwarzen Dreieck; daran angebunden ein <code>SwConnector</code> zu einer Gegenstelle mit nach innen gerichtetem Dreieck.\n</li><li>Fünfter Port: Anfordernder Service-Port mit Verbindung zu einem massiven schwarzen Block (<code>required service PortPrototype, SenderReceiverInterface</code>).\n</li><li>Sechster Port: Bereitgestellter Sender-Receiver-Port (<code>provided PortPrototype, SenderReceiverInterface</code>) mit angehängtem Notiz-Symbol <code>attributes</code>.\n</li></ul>\n<p class=\"fig-p\">Ein Pfeil mit der Beschriftung <code>PortPrototype characterised by PortInterface</code> weist auf das Port-Symbol hin.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Notationsschema ohne dynamische Ablauf- oder Sequenzpfade. Dargestellt ist das Kopplungsprinzip für Client-Server- und Sender-Receiver-Kommunikation über <code>SwConnector</code> zwischen korrespondierenden Ports.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert die verbindliche grafische Syntax für Tooling und Spezifikationsdokumente: Bereitstellung (Provided) versus Anforderung (Required), Trennung der Kommunikationsmuster (Client-Server als Lollipop/Cup, Sender-Receiver als gerichtete Dreiecke), Kennzeichnung von Service-Ports sowie die Anbringung von Port-Attributen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-66ac57c593e09a10", "to": "FIG-846d2014d3a3e244", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-846d2014d3a3e244", "to": "FIG-1a30d45a66d49758", "fr": "R3.2.3", "tr": "R4.0.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-1a30d45a66d49758", "to": "FIG-b489fff0ef1f19c9", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-b489fff0ef1f19c9", "to": "FIG-cee87488e807a4d5", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Komponentenbeschriftung: Umbenennung von <code>AUTOSAR-SW-Component</code> in <code>AUTOSAR Software-Component</code>.\n</li><li>Verbindungselement: Umbenennung der Beschriftung <code>ConnectorPrototype</code> in <code>SwConnector</code>.\n</li><li>Interfacelabels: Entfernung des nachgestellten Punkts bei <code>provided PortPrototype, ClientServerInterface</code> und <code>required PortPrototype, ClientServerInterface</code>.\n</li></ul>"}, {"from": "FIG-cee87488e807a4d5", "to": "FIG-1eea46e01abb7ab7", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
